using System;
using System.Collections.Generic;
using System.Net;
using System.Net.Sockets;
using System.Net.NetworkInformation;
using System.Security.Cryptography;
using System.Text;
using System.Threading;
using System.Web.Script.Serialization;

namespace WindowsTimer {
 sealed class RemoteServer {
  const int Port=43821;
  readonly object gate=new object();
  readonly List<TcpListener> listeners=new List<TcpListener>();
  List<string> tokens;
  volatile bool running;
  int pairAttempts;
  public string PairingCode { get; private set; }
  public DateTime PairingExpires { get; private set; }
  public string Error { get; private set; }
  public List<string> Addresses { get; private set; }
  public Func<string,int,string> ScheduleCommand;
  public Func<string> CancelCommand,StatusCommand;
  public Action TokensChanged;
  public RemoteServer(){Addresses=new List<string>();}

  public bool Start(List<string> allowedTokens) {
   Stop();Error=null;tokens=allowedTokens;Addresses=new List<string>();RotatePairing();running=true;
   foreach(IPAddress ip in PrivateAddresses())try {
    TcpListener l=new TcpListener(ip,Port);l.Start(8);lock(gate)listeners.Add(l);
    Addresses.Add("http://"+ip+":"+Port+"/");Thread t=new Thread(AcceptLoop);t.IsBackground=true;t.Start(l);
   } catch(SocketException ex){Error=ex.Message;}
   if(Addresses.Count==0){running=false;if(String.IsNullOrEmpty(Error))Error="사설 네트워크 주소를 찾지 못했어요.";return false;}
   return true;
  }
  public void Stop(){running=false;lock(gate){foreach(TcpListener l in listeners)try{l.Stop();}catch{}listeners.Clear();}Addresses=new List<string>();}
  public void RotatePairing(){byte[] b=new byte[4];using(RandomNumberGenerator r=RandomNumberGenerator.Create())r.GetBytes(b);PairingCode=(BitConverter.ToUInt32(b,0)%1000000).ToString("D6");PairingExpires=DateTime.Now.AddMinutes(5);pairAttempts=0;}
  public void ClearTokens(){lock(gate){if(tokens!=null)tokens.Clear();}if(TokensChanged!=null)TokensChanged();}
  void AcceptLoop(object state){TcpListener l=(TcpListener)state;while(running)try{TcpClient c=l.AcceptTcpClient();ThreadPool.QueueUserWorkItem(HandleClient,c);}catch(SocketException){return;}catch(ObjectDisposedException){return;}catch{return;}}
  void HandleClient(object state){using(TcpClient client=(TcpClient)state)try{
   client.ReceiveTimeout=7000;client.SendTimeout=7000;NetworkStream stream=client.GetStream();string headers,error;int length;
   if(!ReadHeaders(stream,out headers,out length,out error)){Response(stream,400,"text/plain; charset=utf-8",error);return;}
   if(length>16384){Response(stream,413,"text/plain; charset=utf-8","Request too large");return;}
   byte[] bodyBytes=new byte[length];int read=0;while(read<length){int n=stream.Read(bodyBytes,read,length-read);if(n<=0)break;read+=n;}if(read!=length){Response(stream,400,"text/plain; charset=utf-8","Incomplete request");return;}
   string[] lines=headers.Split(new string[]{"\r\n"},StringSplitOptions.None),first=lines[0].Split(' ');if(first.Length<2){Response(stream,400,"text/plain; charset=utf-8","Bad request");return;}
   string method=first[0].ToUpperInvariant(),path=first[1].Split('?')[0],body=Encoding.UTF8.GetString(bodyBytes);Dictionary<string,string> h=new Dictionary<string,string>(StringComparer.OrdinalIgnoreCase);
   for(int i=1;i<lines.Length;i++){int colon=lines[i].IndexOf(':');if(colon>0)h[lines[i].Substring(0,colon).Trim()]=lines[i].Substring(colon+1).Trim();}
   string host,origin;if(h.TryGetValue("Host",out host)&&h.TryGetValue("Origin",out origin)&&origin!="http://"+host){Response(stream,403,"application/json; charset=utf-8","{\"error\":\"Origin rejected\"}");return;}
   if(method=="GET"&&path=="/"){Response(stream,200,"text/html; charset=utf-8",Page);return;}
   if(method=="POST"&&path=="/api/pair"){Dictionary<string,object>d=Parse(body);object code;if(d==null||!d.TryGetValue("code",out code)){Response(stream,400,"application/json; charset=utf-8","{\"error\":\"코드를 입력해 주세요.\"}");return;}string token=Pair(Convert.ToString(code));if(token==null){Response(stream,403,"application/json; charset=utf-8","{\"error\":\"코드가 틀렸거나 만료됐어요.\"}");return;}Response(stream,200,"application/json; charset=utf-8",Json(new{token=token}));return;}
   if(!Authorized(h)){Response(stream,401,"application/json; charset=utf-8","{\"error\":\"인증이 필요해요.\"}");return;}
   if(method=="GET"&&path=="/api/status"){Response(stream,200,"application/json; charset=utf-8",Json(new{status=StatusCommand==null?"앱 상태 확인 불가":StatusCommand()}));return;}
   if(method=="POST"&&path=="/api/schedule"){Dictionary<string,object>d=Parse(body);object a,m;if(d==null||!d.TryGetValue("action",out a)||!d.TryGetValue("minutes",out m)){Response(stream,400,"application/json; charset=utf-8","{\"error\":\"예약 값을 확인해 주세요.\"}");return;}string action=Convert.ToString(a);int mins;try{mins=Convert.ToInt32(m);}catch{mins=0;}if(mins<2||mins>10080||Array.IndexOf(new string[]{"종료","재부팅","절전","최대 절전"},action)<0){Response(stream,400,"application/json; charset=utf-8","{\"error\":\"동작 또는 시간이 허용 범위를 벗어났어요.\"}");return;}Response(stream,200,"application/json; charset=utf-8",Json(new{status=ScheduleCommand==null?"앱 연결 오류":ScheduleCommand(action,mins)}));return;}
   if(method=="POST"&&path=="/api/cancel"){Response(stream,200,"application/json; charset=utf-8",Json(new{status=CancelCommand==null?"앱 연결 오류":CancelCommand()}));return;}
   if(method=="POST"&&path=="/api/unpair"){RemoveAuthorized(h);Response(stream,200,"application/json; charset=utf-8","{\"ok\":true}");return;}
   Response(stream,404,"application/json; charset=utf-8","{\"error\":\"Not found\"}");
  }catch{}}
  string Pair(string code){lock(gate){if(DateTime.Now>PairingExpires||pairAttempts>=5||tokens==null||tokens.Count>=12)return null;if(!String.Equals(code,PairingCode,StringComparison.Ordinal)){pairAttempts++;return null;}string token=RandomToken();tokens.Add(token);PairingExpires=DateTime.MinValue;if(TokensChanged!=null)ThreadPool.QueueUserWorkItem(delegate{TokensChanged();});return token;}}
  bool Authorized(Dictionary<string,string> h){string a;if(!h.TryGetValue("Authorization",out a)||!a.StartsWith("Bearer ",StringComparison.OrdinalIgnoreCase))return false;lock(gate)return tokens!=null&&tokens.Contains(a.Substring(7).Trim());}
  void RemoveAuthorized(Dictionary<string,string> h){string a;if(!h.TryGetValue("Authorization",out a)||!a.StartsWith("Bearer ",StringComparison.OrdinalIgnoreCase))return;lock(gate)if(tokens!=null)tokens.Remove(a.Substring(7).Trim());if(TokensChanged!=null)TokensChanged();}
  static string RandomToken(){byte[] b=new byte[32];using(RandomNumberGenerator r=RandomNumberGenerator.Create())r.GetBytes(b);return Convert.ToBase64String(b).TrimEnd('=').Replace('+','-').Replace('/','_');}
  static Dictionary<string,object> Parse(string s){try{return new JavaScriptSerializer().Deserialize<Dictionary<string,object>>(s);}catch{return null;}}
  static string Json(object o){return new JavaScriptSerializer().Serialize(o);}
  static bool ReadHeaders(NetworkStream s,out string text,out int length,out string error){StringBuilder b=new StringBuilder();int match=0;length=0;error="Bad headers";text="";while(b.Length<16384){int v=s.ReadByte();if(v<0)return false;char c=(char)v;b.Append(c);if((match==0&&c=='\r')||(match==1&&c=='\n')||(match==2&&c=='\r')||(match==3&&c=='\n'))match++;else match=c=='\r'?1:0;if(match==4)break;}text=b.ToString();if(match!=4)return false;foreach(string line in text.Split(new string[]{"\r\n"},StringSplitOptions.None))if(line.StartsWith("Content-Length:",StringComparison.OrdinalIgnoreCase))Int32.TryParse(line.Substring(15).Trim(),out length);error=null;return true;}
  static void Response(NetworkStream s,int status,string type,string body){byte[] bytes=Encoding.UTF8.GetBytes(body);string title=status==200?"OK":status==401?"Unauthorized":status==403?"Forbidden":status==404?"Not Found":status==413?"Payload Too Large":"Bad Request";string h="HTTP/1.1 "+status+" "+title+"\r\nContent-Type: "+type+"\r\nContent-Length: "+bytes.Length+"\r\nConnection: close\r\nCache-Control: no-store\r\nX-Content-Type-Options: nosniff\r\nContent-Security-Policy: default-src 'self'; script-src 'unsafe-inline'; style-src 'unsafe-inline'; connect-src 'self'; frame-ancestors 'none'\r\n\r\n";byte[] head=Encoding.ASCII.GetBytes(h);s.Write(head,0,head.Length);s.Write(bytes,0,bytes.Length);s.Flush();}
  static List<IPAddress> PrivateAddresses(){List<IPAddress> r=new List<IPAddress>();foreach(NetworkInterface n in NetworkInterface.GetAllNetworkInterfaces()){if(n.OperationalStatus!=OperationalStatus.Up)continue;try{foreach(UnicastIPAddressInformation u in n.GetIPProperties().UnicastAddresses){IPAddress ip=u.Address;if(ip.AddressFamily!=AddressFamily.InterNetwork)continue;byte[] b=ip.GetAddressBytes();bool ok=b[0]==10||(b[0]==172&&b[1]>=16&&b[1]<=31)||(b[0]==192&&b[1]==168)||(b[0]==100&&b[1]>=64&&b[1]<=127);if(ok&&!r.Contains(ip))r.Add(ip);}}catch{}}return r;}
  const string Page="<!doctype html><html lang='ko'><meta charset='utf-8'><meta name='viewport' content='width=device-width,initial-scale=1'><title>윈도우 타이머 원격</title><style>*{box-sizing:border-box}body{margin:0;background:#f6f2eb;color:#372f2a;font:16px 'Segoe UI',sans-serif}.box{max-width:520px;margin:28px auto;padding:24px;background:#fffdf9;border:1px solid #e5dcd0;border-radius:24px;box-shadow:0 12px 36px #372f2a18}h1{font-size:25px;margin:0 0 8px}p{color:#897e73;line-height:1.5}.row{display:flex;gap:10px;margin:14px 0}input,select,button{font:inherit;border-radius:12px;padding:13px;border:1px solid #e5dcd0}input,select{background:#fff;width:100%}button{background:linear-gradient(#be6f4b,#93442a);color:white;border:0;font-weight:700;width:100%;cursor:pointer}.secondary{background:#f1eae0;color:#372f2a}.status{padding:12px;border-radius:12px;background:#eef2ea;margin:14px 0;min-height:44px}.hidden{display:none}.small{font-size:12px}</style><main class='box'><h1>윈도우 타이머</h1><p>휴대폰이나 다른 PC에서 예약을 만들고 취소할 수 있어요. 예약 실행 전 PC에서도 60초 안내가 표시됩니다.</p><section id='pair'><label>PC 화면에 표시된 6자리 연결 코드를 입력하세요<input id='code' inputmode='numeric' maxlength='6' autocomplete='one-time-code'></label><div class='row'><button onclick='pair()'>이 기기 연결</button></div></section><section id='app' class='hidden'><div id='status' class='status'>연결됨</div><label>동작<select id='action'><option value='종료'>종료</option><option value='재부팅'>재부팅</option><option value='절전'>절전</option><option value='최대 절전'>최대 절전</option></select></label><div class='row'><label style='flex:1'>몇 분 뒤<input id='minutes' type='number' min='2' max='10080' value='30'></label></div><div class='row'><button onclick='schedule()'>예약하기</button></div><div class='row'><button class='secondary' onclick='cancelJob()'>예약 취소</button></div><div class='row'><button class='secondary' onclick='unpair()'>이 기기 연결 해제</button></div></section><p class='small'>LAN 통신은 암호화되지 않습니다. 신뢰할 수 있는 네트워크에서만 사용하세요. 외부 접속은 양쪽 기기를 VPN에 연결하세요.</p><div id='message' class='status hidden'></div></main><script>const q=id=>document.getElementById(id),key='windowsTimerRemoteToken';function msg(s){q('message').textContent=local(s);q('message').classList.remove('hidden')}function token(){return localStorage.getItem(key)}async function api(path,data){let r=await fetch(path,{method:data?'POST':'GET',headers:Object.assign({'Authorization':'Bearer '+token()},data?{'Content-Type':'application/json'}:{}),body:data?JSON.stringify(data):undefined});let j=await r.json();if(!r.ok)throw Error(j.error||'요청 실패');return j}async function pair(){try{let r=await fetch('/api/pair',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({code:q('code').value})}),j=await r.json();if(!r.ok)throw Error(j.error);localStorage.setItem(key,j.token);showApp();msg('이 기기를 연결했어요.')}catch(e){msg(e.message)}}function showApp(){q('pair').classList.toggle('hidden',!!token());q('app').classList.toggle('hidden',!token());if(token())refresh()}async function refresh(){try{let x=await api('/api/status');q('status').textContent=local(x.status)}catch(e){localStorage.removeItem(key);showApp();msg(e.message)}}async function schedule(){try{let x=await api('/api/schedule',{action:q('action').value,minutes:Number(q('minutes').value)});msg(x.status);refresh()}catch(e){msg(e.message)}}async function cancelJob(){try{let x=await api('/api/cancel',{});msg(x.status);refresh()}catch(e){msg(e.message)}}async function unpair(){try{await api('/api/unpair',{})}catch(e){}localStorage.removeItem(key);showApp();msg('이 기기의 연결을 해제했어요.')}const locale=(navigator.language||'ko').toLowerCase();let tr={};if(locale.startsWith('ja'))tr={title:'Windows Timer',intro:'スマートフォンや別のPCから予約を作成・キャンセルできます。実行60秒前にはPCにも通知が表示されます。',code:'PC画面に表示された6桁の接続コードを入力してください',pair:'この端末を接続',action:'操作',minutes:'何分後',schedule:'予約する',cancel:'予約を取り消す',unpair:'この端末の接続を解除',note:'LAN通信は暗号化されません。信頼できるネットワークのみで使用してください。外部接続では両方の端末をVPNに接続してください。',connected:'接続済み',scheduled:'予約しました。PCの60秒前通知が表示される前なら取り消せます。',unpaired:'この端末の接続を解除しました。',noSchedule:'予約はありません',paired:'この端末を接続しました。',canceled:'予約を取り消しました。',invalid:'コードが正しくないか、有効期限が切れています。'};else if(locale.startsWith('zh'))tr={title:'Windows Timer',intro:'可通过手机或其他电脑创建和取消预约。执行前 60 秒，电脑也会显示提醒。',code:'请输入电脑屏幕上显示的 6 位连接码',pair:'连接此设备',action:'操作',minutes:'多少分钟后',schedule:'预约',cancel:'取消预约',unpair:'断开此设备',note:'局域网通信未加密。请仅在可信网络中使用。通过互联网访问时，请让两台设备连接 VPN。',connected:'已连接',scheduled:'预约已创建。电脑显示执行前 60 秒提醒之前仍可取消。',unpaired:'此设备已断开。',noSchedule:'没有预约',paired:'此设备已连接。',canceled:'预约已取消。',invalid:'代码错误或已过期。'};else if(locale.startsWith('en'))tr={title:'Windows Timer',intro:'Create or cancel a schedule from your phone or another PC. The PC also shows a warning 60 seconds before it runs.',code:'Enter the 6-digit pairing code shown on the PC',pair:'Pair this device',action:'Action',minutes:'Minutes from now',schedule:'Schedule',cancel:'Cancel schedule',unpair:'Unpair this device',note:'LAN traffic is not encrypted. Use only a trusted network. For internet access, connect both devices through a VPN.',connected:'Connected',scheduled:'Scheduled. You can still cancel on the PC before its 60-second warning.',unpaired:'This device is unpaired.',noSchedule:'No schedule',paired:'This device is paired.',canceled:'Schedule canceled.',invalid:'The code is incorrect or expired.'};function local(s){const m={'예약 없음':tr.noSchedule,'예약했어요. 실행 60초 전에 PC에서 취소할 수 있습니다.':tr.scheduled,'예약을 취소했어요.':tr.canceled,'코드가 틀렸거나 만료됐어요.':tr.invalid,'코드를 입력해 주세요.':'Enter the pairing code.','취소할 일회 예약이 없습니다.':'There is no one-time schedule to cancel.','취소할 예약이 없습니다.':'There is no schedule to cancel.','이 기기를 연결했어요.':tr.paired,'이 기기의 연결을 해제했어요.':tr.unpaired,'연결됨':tr.connected};return m[s]||s}function localize(){if(!tr.title)return;document.documentElement.lang=locale;document.title=tr.title;document.querySelector('h1').textContent=tr.title;document.querySelector('main>p').textContent=tr.intro;q('pair').querySelector('label').firstChild.textContent=tr.code;q('pair').querySelector('button').textContent=tr.pair;q('action').parentElement.firstChild.textContent=tr.action;q('minutes').parentElement.firstChild.textContent=tr.minutes;const buttons=q('app').querySelectorAll('button');buttons[0].textContent=tr.schedule;buttons[1].textContent=tr.cancel;buttons[2].textContent=tr.unpair;document.querySelector('p.small').textContent=tr.note}localize();showApp();</script></html>";
 }

}
